import React, { useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { FitAddon } from 'xterm-addon-fit';
import { AttachAddon } from 'xterm-addon-attach';
import { useXTerm } from 'react-xtermjs';
import 'xterm/css/xterm.css';

const TerminalComponent = () => {
  const { containerId } = useParams();
  const { instance, ref } = useXTerm();
  const fitAddon = new FitAddon();

  useEffect(() => {
    if (instance) {
      instance.loadAddon(fitAddon);
      fitAddon.fit();

      const socket = new WebSocket(`ws://localhost:3001`);

      // Send WebSocket message with TTY allocation
      socket.onopen = () => {
        socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
      };
      const attachAddon = new AttachAddon(socket);
      instance.loadAddon(attachAddon);

      socket.onmessage = (event) => {
        console.log('Received:', event.data);
        const message = JSON.parse(event.data);
        if (message.output) {
          instance.write(message.output);
        } else if (message.error) {
          instance.write(`\x1B[31m${message.error}\x1B[0m`); // Display error in red
        } else if (message.message) {
          instance.write(`${message.message}\n`);
        }
      };

      instance.onData(data => {
        instance.write(data); // Display typed command in terminal
        if (socket.readyState === WebSocket.OPEN) {
          socket.send(JSON.stringify({ containerId, cmd: data }));
        }
      });
      instance.writeln('Welcome to the Docker container terminal!');
      window.addEventListener('resize', () => fitAddon.fit());

      return () => {
        socket.close();
        window.removeEventListener('resize', () => fitAddon.fit());
      };
    }
  }, [instance, containerId]);

  return <div ref={ref} style={{ width: '100%', height: '100%', backgroundColor: 'black' ,color:"white"}} />;
};

export default TerminalComponent;
